import java.util.*;class Product{     private int id;     private String pName;     private double Quantity;     private double Price;     public Product(int id,String pName,double Quantity ,double Price)     {          this.Quantity=Quantity;          this.pName=pName;          this.id=id;          this.Price = Price;     }     public Product(){}      public String getPname()     {        return pName;     }     public double getPrice()     {        return Price;     }     public int getId()     {        return id;     }     public double getQuantity()     {        return Quantity;     }} class ProductVectorApp{       public static void main(String args[])       {              Scanner sc=new Scanner(System.in);              Vector v=new Vector();              Product p=new Product();           do{                   System.out.println("1. Add products ");                   System.out.println("2. Display products");                   System.out.println("3. Search product by name ");                   System.out.println("4. Calculate total inventory value ");                   System.out.println("5. Display out of stock products ");                System.out.println("Entet the Choice ");               int choice = sc.nextInt();               switch(choice)              {                  case 1:                             System.out.println("Entet the Product Id Name Quantity Price ");                             int id=sc.nextInt();                             sc.nextLine();                             String name=sc.nextLine();                             double quantity=sc.nextDouble();                             double price=sc.nextDouble();                             v.add(new Product(id,name,quantity,price));                             break;                  case 2:                             System.out.println("DISPLAY ALL PRODUCT ");                             for(Object o: v)                             {                                  p=(Product)o;                                  System.out.println(p.getPname()+" \t"+p.getId()+" \t"+p.getQuantity()+" \t "+p.getPrice());                             }                             break;                  case 3:                             System.out.println("Enter Product name ");                             sc.nextLine();                             String pname=sc.nextLine();                             for(Object obj: v)                             {                                  p=(Product)obj;                                  if(pname.equals(p.getPname()))                                   {                                  System.out.println(p.getPname()+" \t"+p.getId()+" \t"+p.getQuantity()+" \t "+p.getPrice());                                  }                                  else                                  {                                       System.out.println("Product is not Found ");                                  }                             }                                                                  break;                  case 4:                             System.out.println("TOTAL iNVENTRY IS ");                             double value=0.0;                             for(Object obj: v)                             {                                  p=(Product)obj;                                  value+=p.getQuantity();                             }                             System.out.println(value);                             break;                  case 5:                             System.out.println("Out Of Stock Product ");                             for(Object obj: v)                             {                                  p=(Product)obj;                                  if(p.getQuantity()<=0)                                  {                                  System.out.println(p.getPname()+" \t"+p.getId()+" \t"+p.getQuantity()+" \t "+p.getPrice());                                 }                                                                   }                             break;                  default:                             System.out.println(" this is the wrong choice ");              }            }while(true);                        } }